for (const auto& neighbor : graph.get_neighbors(current_node)) {
        if (!neighbor->visited) {
            double g = current_node->g + graph.get_edge_weight(current_node, neighbor);
            if (neighbor->g == 0 || g < neighbor->g) {
                neighbor->g = g;
                neighbor->h = graph.calculate_distance(neighbor, end_node);
                neighbor->f = neighbor->g + neighbor->h;
                open_list.push_back(neighbor);
                neighbor->visited = true;
            }
        }
    }
